'use strict';

// The real, vulnerable implementation. ANONYMOUS, so its only identity is
// its own position in this file -- which means the decoy declaration in
// index.js is the ONLY node in the entire installed package carrying the
// name the advisory asks for. A name-based export search has nothing else
// it could possibly find.
module.exports = function (input) {
  return 'danger:' + String(input);
};
